45	/**
46	 * Deduplicates file paths by file identity (device + inode) rather than string path.
47	 * This is necessary on case-insensitive filesystems where different case variants
48	 * of the same filename resolve to the same physical file but have different path strings.
49	 *
50	 * @param filePaths Array of file paths to deduplicate
51	 * @returns Object containing deduplicated file paths and a map of path to identity key
52	 */
53	export async function deduplicatePathsByFileIdentity(
54	  filePaths: string[],
55	): Promise<{
56	  paths: string[];
57	  identityMap: Map<string, string>;
58	}> {
59	  if (filePaths.length === 0) {
60	    return {
61	      paths: [],
62	      identityMap: new Map<string, string>(),
63	    };
64	  }
65	
66	  // first deduplicate by string path to avoid redundant stat calls
67	  const uniqueFilePaths = Array.from(new Set(filePaths));
68	
69	  const fileIdentityMap = new Map<string, string>();
70	  const deduplicatedPaths: string[] = [];
71	
72	  const CONCURRENT_LIMIT = 20;
73	  const results: Array<{
74	    path: string;
75	    dev: bigint | number | null;
76	    ino: bigint | number | null;
77	  }> = [];
78	
79	  for (let i = 0; i < uniqueFilePaths.length; i += CONCURRENT_LIMIT) {
80	    const batch = uniqueFilePaths.slice(i, i + CONCURRENT_LIMIT);
81	    const batchPromises = batch.map(async (filePath) => {
82	      try {
83	        // use stat() instead of lstat() to follow symlinks and get target file identity
84	        const stats = await fs.stat(filePath);
85	        return {
86	          path: filePath,
87	          dev: stats.dev,
88	          ino: stats.ino,
89	        };
90	      } catch (error: unknown) {
91	        const message = error instanceof Error ? error.message : String(error);
92	        logger.debug(
93	          `could not stat file for deduplication: ${filePath}. error: ${message}`,
94	        );
95	        return {
96	          path: filePath,
97	          dev: null,
98	          ino: null,
99	        };
100	      }
101	    });
102	
103	    const batchResults = await Promise.allSettled(batchPromises);
104	    for (const result of batchResults) {
105	      if (result.status === 'fulfilled') {
106	        results.push(result.value);
107	      } else {
108	        const message = getErrorMessage(result.reason);
109	        debugLogger.debug(
110	          '[DEBUG] [MemoryDiscovery] unexpected error during deduplication stat:',
111	          message,
112	        );
113	      }
114	    }
115	  }
116	
117	  const pathToIdentityMap = new Map<string, string>();
118	  for (const { path, dev, ino } of results) {
119	    if (dev !== null && ino !== null) {
120	      const identityKey = `${dev.toString()}:${ino.toString()}`;
121	      pathToIdentityMap.set(path, identityKey);
122	      if (!fileIdentityMap.has(identityKey)) {
123	        fileIdentityMap.set(identityKey, path);
124	        deduplicatedPaths.push(path);
125	        debugLogger.debug(
126	          '[DEBUG] [MemoryDiscovery] deduplication: keeping',
127	          path,
128	          `(dev: ${dev}, ino: ${ino})`,
129	        );
130	      } else {
131	        const existingPath = fileIdentityMap.get(identityKey);
132	        debugLogger.debug(
133	          '[DEBUG] [MemoryDiscovery] deduplication: skipping',
134	          path,
135	          `(same file as ${existingPath})`,
136	        );
137	      }
138	    } else {
139	      deduplicatedPaths.push(path);
140	    }
141	  }
142	
143	  return {
144	    paths: deduplicatedPaths,
145	    identityMap: pathToIdentityMap,
146	  };
147	}
