149	async function findProjectRoot(startDir: string): Promise<string | null> {
150	  let currentDir = normalizePath(startDir);
151	  while (true) {
152	    const gitPath = path.join(currentDir, '.git');
153	    try {
154	      // Check for existence only — .git can be a directory (normal repos)
155	      // or a file (submodules / worktrees).
156	      await fs.access(gitPath);
157	      return currentDir;
158	    } catch (error: unknown) {
159	      // Don't log ENOENT errors as they're expected when .git doesn't exist
160	      // Also don't log errors in test environments, which often have mocked fs
161	      const isENOENT =
162	        typeof error === 'object' &&
163	        error !== null &&
164	        'code' in error &&
165	        // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
166	        (error as { code: string }).code === 'ENOENT';
167	
168	      // Only log unexpected errors in non-test environments
169	      // process.env['NODE_ENV'] === 'test' or VITEST are common test indicators
170	      const isTestEnv =
171	        process.env['NODE_ENV'] === 'test' || process.env['VITEST'];
172	
173	      if (!isENOENT && !isTestEnv) {
174	        if (typeof error === 'object' && error !== null && 'code' in error) {
175	          // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
176	          const fsError = error as { code: string; message: string };
177	          logger.warn(
178	            `Error checking for .git at ${gitPath}: ${fsError.message}`,
179	          );
180	        } else {
181	          logger.warn(
182	            `Non-standard error checking for .git at ${gitPath}: ${String(error)}`,
183	          );
184	        }
185	      }
186	    }
187	    const parentDir = normalizePath(path.dirname(currentDir));
188	    if (parentDir === currentDir) {
189	      return null;
190	    }
191	    currentDir = parentDir;
192	  }
193	}
